+    /** Renders the cycle as {@code 0 -> 1 -> 2 -> 0}. */
+    @Override
+    public String toString() {
+        StringBuilder sb = new StringBuilder();
+        for (int i = 0; i < vertices.size(); i++) {
+            if (i > 0) {
+                sb.append(" -> ");
