+            assertEquals(Optional.empty(), detector.findCycle(graph));
+        }
+
+        @Test
+        @DisplayName("returns a valid closed walk along graph edges")
+        void returnsValidCycle() {
+            DirectedGraph graph = DirectedGraph.from(4, new int[][] {
+                {0, 1}, {1, 2}, {2, 0}, {2, 3}
